per_step.command:
awk -F',' 'BEGIN {print "=== NHB AUDIT - PATIENT RECORDS VALIDATION REPORT ==="} 
NR==1 {header=$0; next}
{
  missing=""
  if($2=="") missing=missing"first_name "
  if($3=="") missing=missing"last_name "
  if($4=="") missing=missing"birth_date "
  if($5=="") missing=missing"admission_date "
  if($6=="") missing=missing"discharge_date "
  if($7=="") missing=missing"diagnosis "
  if($8=="") missing=missing"doctor "
  if($9=="") missing=missing"treatment "

  if(missing!="") {
    print "\n[CRITICAL] Patient ID " $1 ": Missing fields - " missing
    incomplete++
  } else {
    complete++
  }
}
END {
  print "\n=== SUMMARY ==="
  print "Total records: " (complete+incomplete)
  print "Complete records: " complete
  print "Incomplete records: " incomplete
  if((complete+incomplete) > 0) {
    completion_rate = (complete/(complete+incomplete))*100
    printf "Completion rate: %.0f%%\n", completion_rate
  }

  if(incomplete > 0) {
    print "\n=== ACTION REQUIRED ==="
    print "The following Patient IDs have incomplete records and MUST be reviewed"
    print "by authorized medical personnel before the NHB audit:"
    print "  - Patient ID 2: Missing discharge_date"
    print "  - Patient ID 4: Missing admission_date"
    print "\n⚠️  DO NOT fabricate data. All updates must be verified by medical staff."
  } else {
    print "\n✓ All records are complete and ready for NHB audit submission."
  }
}' /app/data/patient_records.csv
